-- LITTX Website v2.0 initial schema. Run in Supabase SQL editor or with Supabase CLI.
create extension if not exists pgcrypto;
create type public.plan_code as enum ('FREE','LITTX_PLUS','LITTX_FIRE');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, username text unique not null check(length(username) between 3 and 24), created_at timestamptz not null default now(), is_banned boolean not null default false);
create table public.products(id uuid primary key default gen_random_uuid(), code public.plan_code unique not null, name text not null, active boolean not null default true);
insert into public.products(code,name) values ('FREE','LITTX FREE'),('LITTX_PLUS','LITTX+'),('LITTX_FIRE','LITTX FIRE') on conflict do nothing;
create table public.entitlements(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, plan public.plan_code not null check(plan <> 'FREE'), status text not null default 'active' check(status in ('active','revoked','expired')), starts_at timestamptz not null default now(), expires_at timestamptz, source text not null default 'admin', created_at timestamptz not null default now(), check(expires_at is null or expires_at > starts_at));
create index entitlements_user_plan_idx on public.entitlements(user_id,plan,status);
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan public.plan_code not null,starts_at timestamptz not null default now(),expires_at timestamptz,status text not null default 'active',payment_id uuid,created_at timestamptz not null default now());
create table public.vouchers(id uuid primary key default gen_random_uuid(),code text unique not null,name text,description text,plan public.plan_code not null check(plan <> 'FREE'),duration_days integer not null check(duration_days in (0,30)),max_uses integer not null check(max_uses>0),uses integer not null default 0 check(uses>=0 and uses<=max_uses),expires_at timestamptz,is_enabled boolean not null default true,created_at timestamptz not null default now());
create table public.voucher_redemptions(id uuid primary key default gen_random_uuid(),voucher_id uuid not null references public.vouchers(id),user_id uuid not null references auth.users(id),redeemed_at timestamptz not null default now(),unique(voucher_id,user_id));
create table public.payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),provider text not null,provider_reference text unique,status text not null check(status in ('pending','confirmed','failed','refunded')),amount_minor integer not null check(amount_minor>0),currency text not null default 'USD',plan public.plan_code not null,created_at timestamptz not null default now(),confirmed_at timestamptz);
create table public.discounts(id uuid primary key default gen_random_uuid(),name text not null,percent integer not null check(percent between 1 and 90),products public.plan_code[] not null,starts_at timestamptz not null,ends_at timestamptz not null,is_active boolean not null default false,check(ends_at>starts_at));
create table public.releases(id uuid primary key default gen_random_uuid(),version text not null,file_name text not null,storage_path text not null unique,release_notes text,required_plan public.plan_code not null default 'FREE',is_published boolean not null default false,file_size bigint,download_count bigint not null default 0,created_at timestamptz not null default now());
create table public.download_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),release_id uuid not null references public.releases(id) on delete cascade,downloaded_at timestamptz not null default now());
create table public.discord_settings(id integer primary key default 1 check(id=1),guild_id text,plus_role_id text,fire_role_id text,enabled boolean not null default false);
create table public.admin_audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,target_type text,target_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'username',''),split_part(new.email,'@',1))); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create function public.user_has_plan(p_user_id uuid,p_plan public.plan_code) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.entitlements e where e.user_id=p_user_id and e.plan=p_plan and e.status='active' and e.starts_at<=now() and (e.expires_at is null or e.expires_at>now())) or (p_plan='LITTX_PLUS' and exists(select 1 from public.entitlements e where e.user_id=p_user_id and e.plan='LITTX_FIRE' and e.status='active' and e.starts_at<=now() and (e.expires_at is null or e.expires_at>now()))); $$;
create function public.redeem_voucher(p_code text,p_user_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare v public.vouchers%rowtype; expiry timestamptz; begin select * into v from public.vouchers where code=upper(trim(p_code)) for update; if not found or not v.is_enabled then raise exception 'Voucher is invalid or disabled'; end if; if v.expires_at is not null and v.expires_at<=now() then raise exception 'Voucher has expired'; end if; if v.uses>=v.max_uses then raise exception 'Voucher has reached its usage limit'; end if; if exists(select 1 from public.voucher_redemptions where voucher_id=v.id and user_id=p_user_id) then raise exception 'This account has already redeemed this voucher'; end if; update public.vouchers set uses=uses+1 where id=v.id; insert into public.voucher_redemptions(voucher_id,user_id) values(v.id,p_user_id); expiry:=case when v.duration_days=0 then null else now()+make_interval(days=>v.duration_days) end; insert into public.entitlements(user_id,plan,expires_at,source) values(p_user_id,v.plan,expiry,'voucher'); insert into public.subscriptions(user_id,plan,expires_at,status) values(p_user_id,v.plan,expiry,'active'); return jsonb_build_object('success',true,'plan',v.plan,'expires_at',expiry); end; $$;
alter table public.profiles enable row level security;alter table public.products enable row level security;alter table public.entitlements enable row level security;alter table public.subscriptions enable row level security;alter table public.vouchers enable row level security;alter table public.voucher_redemptions enable row level security;alter table public.payments enable row level security;alter table public.discounts enable row level security;alter table public.releases enable row level security;alter table public.download_logs enable row level security;alter table public.discord_settings enable row level security;alter table public.admin_audit_logs enable row level security;
create policy "profiles read own" on public.profiles for select to authenticated using(auth.uid()=id);create policy "profiles update own username" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy "public products" on public.products for select to anon,authenticated using(active);create policy "users read own entitlements" on public.entitlements for select to authenticated using(auth.uid()=user_id);create policy "users read own subscriptions" on public.subscriptions for select to authenticated using(auth.uid()=user_id);create policy "public active discounts" on public.discounts for select to anon,authenticated using(is_active and starts_at<=now() and ends_at>now());create policy "public published releases metadata" on public.releases for select to anon,authenticated using(is_published);create policy "users read own download logs" on public.download_logs for select to authenticated using(auth.uid()=user_id);
-- No client-side policies for vouchers, redemptions, payments, Discord settings or audit logs. Server service-role operations only.
revoke all on function public.redeem_voucher(text,uuid) from public, anon, authenticated;
grant execute on function public.redeem_voucher(text,uuid) to service_role;
revoke all on function public.user_has_plan(uuid,public.plan_code) from public, anon, authenticated;
grant execute on function public.user_has_plan(uuid,public.plan_code) to service_role;
